import{z as n,x as s,o as A,c as o,q as B,j as t,D as a,d as l,s as r,S as i}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"训练基础设施收束","description":"","frontmatter":{"title":"训练基础设施收束","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/ti-map.md","filePath":"llm/ti-map.md","lastUpdated":1791413859000}'),D={name:"llm/ti-map.md"};function p(d,E,m,h,C,_){const e=s("Mermaid");return A(),o("div",null,[E[2]||(E[2]=B('<h1 id="训练基础设施收束" tabindex="-1">训练基础设施收束 <a class="header-anchor" href="#训练基础设施收束" aria-label="Permalink to &quot;训练基础设施收束&quot;">​</a></h1><div class="epigraph"><p>基础设施的知识点会过时，账不会：骨架、契约与记账口径是这套课程的剩余物，其余皆可换代。</p><footer>—— 据本课程十四课整理</footer></div><p><a href="/llm/ti-cost-analysis">上一课</a>把账算到货币，十三课从 step 骨架走到数据、快照、观测、实验，再走到人、流程与钱。本课不添新内容，把决策收成三张单：新项目按单走一遍，老项目拿单来对账。本课程到此收束。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>为什么要收束：十四课的细节——预取槽深、双环保留、绊网分级——都会随工具换代失效，但事故的类型不会。收束课的任务与端侧收束同构：把每类事故倒推回它该被拦住的那一课，让细节退场后，防线仍在。训练基础设施的失败很少是「算法不行」，多数是账没建：数据指纹缺失导致续训换了轨迹、配置哈希分叉导致对比作废、死因没写导致学费重交。三类病根相同：某张单没有真的在跑。</p><h3 id="三张单" tabindex="-1">三张单 <a class="header-anchor" href="#三张单" aria-label="Permalink to &quot;三张单&quot;">​</a></h3><p><strong>决策单</strong>九步按依赖排：一，解剖 step 骨架，定钩子节奏（<a href="/llm/ti-training-loop-anatomy">训练循环的解剖</a>）；二，数据流水线三账——吞吐、确定性、变更（<a href="/llm/ti-data-pipeline">数据加载与预处理流水线</a>）；三，检查点四件套——层级、定频、保留、分线（<a href="/llm/ti-checkpoint-engineering">checkpoint 工程深入</a>）；四，观测三层——曲线口径、直方图形状、数值绊网（<a href="/llm/ti-loss-curve-reading">loss 曲线的解读</a>至<a href="/llm/ti-numerical-health">数值健康检查</a>）；五，搜索预算封顶一成、产出响应面（<a href="/llm/ti-hparam-search-eng">超参搜索工程</a>）；六，跟踪库记身份四元组与判词；七，调度分三型、抢占挂检查点；八，归档五分类、死因落判据；九，配方六组字段走版本评审，成本三层记账（<a href="/llm/ti-cost-analysis">成本分析</a>）。</p>',7)),(A(),t(i,null,{default:a(()=>[r(e,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E9%AA%A8%E6%9E%B6%E4%B8%8E%E9%92%A9%E5%AD%90%E8%8A%82%E5%A5%8F%22%5D%20--%3E%20B%5B%22%E6%B5%81%E6%B0%B4%E7%BA%BF%E4%B8%89%E8%B4%A6%22%5D%0A%20%20B%20--%3E%20C%5B%22%E6%A3%80%E6%9F%A5%E7%82%B9%E5%9B%9B%E4%BB%B6%E5%A5%97%22%5D%0A%20%20C%20--%3E%20D%5B%22%E8%A7%82%E6%B5%8B%3A%20%E6%9B%B2%E7%BA%BF%20%2F%20%E7%9B%B4%E6%96%B9%E5%9B%BE%20%2F%20%E7%BB%8A%E7%BD%91%22%5D%0A%20%20D%20--%3E%20E%5B%22%E6%90%9C%E7%B4%A2%3A%20%E9%A2%84%E7%AE%97%E5%B0%81%E9%A1%B6%20%2B%20%E5%93%8D%E5%BA%94%E9%9D%A2%22%5D%0A%20%20E%20--%3E%20F%5B%22%E8%B7%9F%E8%B8%AA%3A%20%E5%9B%9B%E5%85%83%E7%BB%84%20%2B%20%E5%88%A4%E8%AF%8D%22%5D%0A%20%20F%20--%3E%20G%5B%22%E8%B0%83%E5%BA%A6%E4%B8%89%E5%9E%8B%20%2B%20%E5%BD%92%E6%A1%A3%E4%BA%94%E5%88%86%E7%B1%BB%22%5D%0A%20%20G%20--%3E%20H%5B%22%E9%85%8D%E6%96%B9%E5%85%AD%E7%BB%84%20%2B%20%E6%88%90%E6%9C%AC%E4%B8%89%E5%B1%82%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[l(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=B('<h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>三条不变量横贯九步。其一，<strong>轨迹契约</strong>：任何旁路设施——评测、存盘、监控——开与关的逐步损失逐点重合；答不出「它为什么不改变轨迹」的旁路是隐患。其二，<strong>指纹唯一</strong>：配置哈希、数据指纹、检查点指针在全链路同源同值，三处分叉则一切对比作废。其三，<strong>账随时可查</strong>：数据从哪来、配置是哪版、钱花在哪、死因为什么，四问在十分钟内可答；答不出的环节就是欠账。高频拦错事六件：只存权重当检查点；混画口径不一的损失曲线；配置哈希三处不一；顺手改配置不入档；尖峰当噪声不归档；死因栏写「效果不好」。六件在十三课里各占一课的份量，收束时并成一排。</p><p><span class="marginnote">术语翻译：不变量就是「无论工具怎么换代都必须成立的性质」，类似物理里的守恒律。轨迹契约说旁路不改变训练结果，指纹唯一说全链路共用同一份身份，账随时可查说四问十分钟内可答——调度器与跟踪系统都是易耗品，这三条才是地基。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>为什么按「决策单、不变量、拦错事」收而不是按章节复述：九步的依赖顺序就是故障的传播路径——骨架上没定钩子节奏，第四步的观测永远缺数据；指纹不唯一，后面一切对比与归档都在流沙上。对账因此从后往前问：成本报表为什么有僵尸作业、死因档案为什么找不到判据、跟踪库为什么对不上检查点——每一步都能指回前一步，这套设施才算真的在跑。</p><p><span class="marginnote">直觉类比：对账像验钞——不从第一张纸的造纸厂查起，而是拿紫外线灯照成品，哪里荧光不对就倒回那一道工序。设施审计同理：从成本、死因这些最末端的现象倒查，每一处异常都要能指回上游哪一步的欠账。</span></p>',6)),(A(),t(i,null,{default:a(()=>[r(e,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20AUD%5B%22%E5%8D%81%E5%88%86%E9%92%9F%E5%AF%B9%E8%B4%A6%3A%20%E4%BB%BB%E5%8F%96%E4%B8%80%E5%9C%BA%20run%20%E9%97%AE%E5%9B%9B%E9%97%AE%22%5D%20--%3E%20Q1%5B%22%E9%92%B1%3A%20%E8%8A%B1%E5%9C%A8%E5%93%AA%2C%20%E8%B0%81%E5%9C%A8%E7%A9%BA%E8%BD%AC%3F%22%5D%0A%20%20AUD%20--%3E%20Q2%5B%22%E6%AD%BB%E5%9B%A0%3A%20%E4%B8%BA%E4%BB%80%E4%B9%88%E5%81%9C%3F%22%5D%0A%20%20AUD%20--%3E%20Q3%5B%22%E9%85%8D%E7%BD%AE%3A%20%E5%BD%93%E6%97%B6%E6%98%AF%E5%93%AA%E4%B8%80%E7%89%88%3F%22%5D%0A%20%20AUD%20--%3E%20Q4%5B%22%E6%95%B0%E6%8D%AE%3A%20%E4%BB%8E%E5%93%AA%E6%9D%A5%3F%22%5D%0A%20%20Q1%20--%3E%7C%E7%AD%94%E4%B8%8D%E5%87%BA%7C%20D9%5B%22%E6%AC%A0%E8%B4%A6%3A%20%E6%88%90%E6%9C%AC%E4%B8%89%E5%B1%82%E8%AE%B0%E8%B4%A6%2C%20%E7%AC%AC%E4%B9%9D%E6%AD%A5%22%5D%0A%20%20Q2%20--%3E%7C%E7%AD%94%E4%B8%8D%E5%87%BA%7C%20D8%5B%22%E6%AC%A0%E8%B4%A6%3A%20%E5%BD%92%E6%A1%A3%E4%BA%94%E5%88%86%E7%B1%BB%2C%20%E7%AC%AC%E5%85%AB%E6%AD%A5%22%5D%0A%20%20Q3%20--%3E%7C%E7%AD%94%E4%B8%8D%E5%87%BA%7C%20D6%5B%22%E6%AC%A0%E8%B4%A6%3A%20%E8%BA%AB%E4%BB%BD%E5%9B%9B%E5%85%83%E7%BB%84%2C%20%E7%AC%AC%E5%85%AD%E6%AD%A5%22%5D%0A%20%20Q4%20--%3E%7C%E7%AD%94%E4%B8%8D%E5%87%BA%7C%20D2%5B%22%E6%AC%A0%E8%B4%A6%3A%20%E6%95%B0%E6%8D%AE%E6%8C%87%E7%BA%B9%2C%20%E7%AC%AC%E4%BA%8C%E6%AD%A5%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[l(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=B('<p><span class="marginnote">对账的硬指标：拿最近一次事故或废掉的 run 回放，能否在十分钟内指出它违反哪条不变量、该在九步的哪一步被拦住——指不出来，说明三张单没有真的在跑。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课程管训练基础设施的骨架、契约与账，不管并行怎么摊卡、通信怎么重叠——那是「分布式训练深入」的起点，与本课的骨架直接相接；RL 那种训练与采样交替的双引擎循环另起系统；数值方案的机理归低精度各课，本课只负责盯着它们别漏水。工具与数字会过时：检查点 API、调度器、跟踪系统都会换代，课程钉住的是 step 作为记账单位、指纹作为可比性地基、判据作为止损起点这三层不变量。云端预算与调度的对应内容在服务各课程，与端侧、训练三条线在各自的收束课各自归账。</p><p><span class="marginnote">常见误区：初学者容易把收束当成「把十四课笔记再抄一遍」，实际上收束的产出是三张单——可执行的决策单、可校验的不变量、可扫视的拦错事清单。笔记是知识，三张单是防线；前者躺在文档里等人读，后者每周都在真实地拦错。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>决策单九步按依赖排：骨架、流水线、检查点、观测、搜索、跟踪、调度与归档、配方与成本。</li><li>三条不变量：轨迹契约、指纹唯一、账随时可查。</li><li>六件高频拦错事：权重当快照、混画曲线、哈希分叉、改配置不入档、尖峰不归档、死因不落判据。</li><li>对账从后往前指：每一步的异常都能指回前一步的欠账。</li><li>出处：按本课程十四课整理；数量级与口径见各课出处行。</li></ul>',6))])}const u=n(D,[["render",p]]);export{f as __pageData,u as default};
